  private Document parseXmlStream(InputStream xmlStream) throws ParserException {
    final DocumentBuilderFactory factory = createSecureXmlFactory();
    final DocumentBuilder builder = createXmlDocumentBuilder(factory);
    try {
      if (xmlEntityResolver != null) {
        builder.setEntityResolver(xmlEntityResolver);
      }
      if (xmlErrorHandler != null) {
        builder.setErrorHandler(xmlErrorHandler);
      }
      return builder.parse(xmlStream);
    } catch (Exception se) {
      throw new ParserException("Error parsing XML stream: " + se, se);
    }
  }

  private DocumentBuilderFactory createSecureXmlFactory() {
    final DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
    dbf.setValidating(false);
    try {
      dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    } catch (
        @SuppressWarnings("unused")
        ParserConfigurationException e) {
      // implementations are required to support secure processing
    }
    return dbf;
  }

  private DocumentBuilder createXmlDocumentBuilder(DocumentBuilderFactory factory)
      throws ParserException {
    try {
      return factory.newDocumentBuilder();
    } catch (Exception se) {
      throw new ParserException("XML Parser configuration error.", se);
    }
  }

