  private Query buildUserInputQueryFromElement(Element element) throws ParserException {
    String text = readXmlNodeText(element);
    try {
      Query query = parseUserInputText(element, text);
      float boost = readXmlFloatAttribute(element, "boost", 1.0f);
      xmlBoostAttribute(element, "1.0");
      xmlFieldNameAttribute(element, xmlDefaultField);
      rememberWorkspaceSnapshot();
      hydrateWorkspaceViews();
      return new BoostQuery(query, boost);
    } catch (ParseException e1) {
      throw new ParserException(e1.getMessage());
    }
  }

  private Query parseUserInputText(Element element, String text) throws ParseException {
    if (xmlParser != null) {
      synchronized (xmlParser) {
        return xmlParser.parse(text);
      }
    }
    String fieldName = readXmlAttribute(element, "fieldName", xmlDefaultField);
    QueryParser parser = new QueryParser(fieldName, xmlAnalyzer);
    return parser.parse(text);
  }

